using System;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using Microsoft.Win32.SafeHandles;
public static class M12OutputFile {
 public readonly record struct Identity(uint Volume,uint High,uint Low,uint Links,string FinalPath);
 public static Identity Read(FileStream stream) { if(!GetFileInformationByHandle(stream.SafeFileHandle,out var info)) throw new InvalidOperationException("file identity unavailable"); var b=new StringBuilder(32768); uint n=GetFinalPathNameByHandle(stream.SafeFileHandle,b,(uint)b.Capacity,0); if(n==0||n>=b.Capacity) throw new InvalidOperationException("final path unavailable"); return new Identity(info.VolumeSerialNumber,info.FileIndexHigh,info.FileIndexLow,info.NumberOfLinks,b.ToString()); }
 [StructLayout(LayoutKind.Sequential)] struct INFO { public uint Attributes; public System.Runtime.InteropServices.ComTypes.FILETIME Created,Accessed,Written; public uint VolumeSerialNumber,SizeHigh,SizeLow,NumberOfLinks,FileIndexHigh,FileIndexLow; }
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandle(SafeFileHandle h,out INFO i);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern uint GetFinalPathNameByHandle(SafeFileHandle h,StringBuilder b,uint n,uint flags);
}
'@
