if($IsWindows -and -not ('M12SuspendedProcess' -as [type])) {
Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
using System.IO;
public sealed class M12SuspendedProcess : IDisposable {
    const uint CreateSuspended=4, CreateNoWindow=0x08000000, KillOnClose=0x2000; const int ExtendedLimits=9, ProcessIdInfoClass=3;
    IntPtr process, thread, job, stdoutRead, stderrRead; public int ProcessId { get; private set; } public Process ManagedProcess { get; private set; }
    M12SuspendedProcess(IntPtr p, IntPtr t, IntPtr j, IntPtr output, IntPtr error, int id) { process=p;thread=t;job=j;stdoutRead=output;stderrRead=error;ProcessId=id;ManagedProcess=Process.GetProcessById(id); }
    public Stream StandardOutput => new FileStream(new Microsoft.Win32.SafeHandles.SafeFileHandle(stdoutRead,false),FileAccess.Read,4096,false);
    public Stream StandardError => new FileStream(new Microsoft.Win32.SafeHandles.SafeFileHandle(stderrRead,false),FileAccess.Read,4096,false);
    public static M12SuspendedProcess Start(string executable,string[] args,string workingDirectory) {
        var command=new StringBuilder(Quote(executable)); foreach(var arg in args) command.Append(' ').Append(Quote(arg));
        var si=new STARTUPINFO(); si.cb=Marshal.SizeOf<STARTUPINFO>(); si.flags=0x100; si.input=GetStdHandle(-10); IntPtr outputRead,outputWrite,errorRead,errorWrite; var security=new SECURITY_ATTRIBUTES{length=Marshal.SizeOf<SECURITY_ATTRIBUTES>(),inherit=1}; if(!CreatePipe(out outputRead,out outputWrite,ref security,0)||!CreatePipe(out errorRead,out errorWrite,ref security,0)||!SetHandleInformation(outputRead,1,0)||!SetHandleInformation(errorRead,1,0)) throw new InvalidOperationException("pipe failed"); si.output=outputWrite;si.error=errorWrite; PROCESS_INFORMATION pi;
        if(!CreateProcess(null,command,IntPtr.Zero,IntPtr.Zero,true,CreateSuspended|CreateNoWindow,IntPtr.Zero,workingDirectory,ref si,out pi)) throw new InvalidOperationException("CreateProcess failed"); CloseHandle(outputWrite);CloseHandle(errorWrite);
        var j=CreateJobObject(IntPtr.Zero,null); if(j==IntPtr.Zero) { TerminateProcess(pi.hProcess,1); throw new InvalidOperationException("CreateJobObject failed"); }
        var limits=new EXTENDED_LIMIT_INFORMATION(); limits.BasicLimitInformation.LimitFlags=KillOnClose;
        if(!SetInformationJobObject(j,ExtendedLimits,ref limits,(uint)Marshal.SizeOf<EXTENDED_LIMIT_INFORMATION>() ) || !AssignProcessToJobObject(j,pi.hProcess) || ResumeThread(pi.hThread)==uint.MaxValue) { TerminateJobObject(j,1); throw new InvalidOperationException("job containment failed"); }
        CloseHandle(pi.hThread); return new M12SuspendedProcess(pi.hProcess,IntPtr.Zero,j,outputRead,errorRead,pi.dwProcessId);
    }
    static string Quote(string v) { var b=new StringBuilder("\""); int slash=0; foreach(char c in v) { if(c=='\\'){slash++;continue;} if(c=='\"'){b.Append('\\',slash*2+1).Append('"');slash=0;continue;} b.Append('\\',slash).Append(c);slash=0;} b.Append('\\',slash*2).Append('"');return b.ToString(); }
     public int ActiveProcesses { get { IntPtr b=Marshal.AllocHGlobal(65536); try { if(!QueryInformationJobObject(job,ProcessIdInfoClass,b,65536,IntPtr.Zero)) throw new InvalidOperationException(); return Marshal.ReadInt32(b); } finally { Marshal.FreeHGlobal(b); } } }
     public int[] ProcessIds { get { IntPtr b=Marshal.AllocHGlobal(65536); try { if(!QueryInformationJobObject(job,ProcessIdInfoClass,b,65536,IntPtr.Zero)) throw new InvalidOperationException(); int n=Marshal.ReadInt32(b,4); var ids=new int[n]; for(int i=0;i<n;i++) ids[i]=unchecked((int)Marshal.ReadInt64(b,8+i*IntPtr.Size)); return ids; } finally { Marshal.FreeHGlobal(b); } } }
    public void Terminate() { if(job!=IntPtr.Zero && !TerminateJobObject(job,1)) throw new InvalidOperationException("TerminateJobObject failed"); }
    public bool WaitForZero(int ms) { long until=Environment.TickCount64+ms; while(Environment.TickCount64<until){if(ProcessIds.Length==0)return true;System.Threading.Thread.Sleep(25);}return ProcessIds.Length==0; }
     public void Dispose() { try { if(ActiveProcesses>0)Terminate(); if(!WaitForZero(2000)) throw new InvalidOperationException("process cleanup timeout"); } finally { if(process!=IntPtr.Zero)CloseHandle(process); if(job!=IntPtr.Zero)CloseHandle(job); if(stdoutRead!=IntPtr.Zero)CloseHandle(stdoutRead); if(stderrRead!=IntPtr.Zero)CloseHandle(stderrRead); } }
     [StructLayout(LayoutKind.Sequential)] struct STARTUPINFO { public int cb; public IntPtr reserved,desktop,title; public int x,y,xSize,ySize,xCount,yCount,fill; public uint flags; public short show,reserved2; public IntPtr reserved3,input,output,error; }
     [StructLayout(LayoutKind.Sequential)] struct SECURITY_ATTRIBUTES { public int length; public IntPtr descriptor; public int inherit; }
    [StructLayout(LayoutKind.Sequential)] struct PROCESS_INFORMATION { public IntPtr hProcess,hThread; public int dwProcessId,dwThreadId; }
    [StructLayout(LayoutKind.Sequential)] struct BASIC_LIMIT_INFORMATION { public long a,b; public uint LimitFlags; public UIntPtr c,d; public uint e; public UIntPtr f; public uint g,h; }
    [StructLayout(LayoutKind.Sequential)] struct IO_COUNTERS { public ulong a,b,c,d,e,f; }
    [StructLayout(LayoutKind.Sequential)] struct EXTENDED_LIMIT_INFORMATION { public BASIC_LIMIT_INFORMATION BasicLimitInformation; public IO_COUNTERS IoInfo; public UIntPtr a,b,c,d; }
     [DllImport("kernel32.dll",SetLastError=true)] static extern bool CreatePipe(out IntPtr read,out IntPtr write,ref SECURITY_ATTRIBUTES attributes,uint size=0); [DllImport("kernel32.dll",SetLastError=true)] static extern bool SetHandleInformation(IntPtr handle,uint mask,uint flags); [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr GetStdHandle(int standardHandle);
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool CreateProcess(string app,StringBuilder cmd,IntPtr pa,IntPtr ta,bool inherit,uint flags,IntPtr env,string cwd,ref STARTUPINFO si,out PROCESS_INFORMATION pi);
    [DllImport("kernel32.dll")] static extern uint ResumeThread(IntPtr thread); [DllImport("kernel32.dll")] static extern IntPtr CreateJobObject(IntPtr a,string n); [DllImport("kernel32.dll")] static extern bool AssignProcessToJobObject(IntPtr j,IntPtr p); [DllImport("kernel32.dll")] static extern bool SetInformationJobObject(IntPtr j,int c,ref EXTENDED_LIMIT_INFORMATION i,uint n); [DllImport("kernel32.dll")] static extern bool QueryInformationJobObject(IntPtr j,int c,IntPtr i,uint n,IntPtr r); [DllImport("kernel32.dll")] static extern bool TerminateJobObject(IntPtr j,uint c); [DllImport("kernel32.dll")] static extern bool TerminateProcess(IntPtr p,uint c); [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
}
'@
}
function Fail([string]$Code) { throw "M12-SUPPLY-CHAIN-PRODUCER-$Code" }
function Assert-M12NoAlternateDataStreams([string]$Path,[string]$Root) { if(-not$IsWindows-or-not(Test-Path -LiteralPath $Path)){return};Assert-M12NoReparse $Path $Root;$item=Get-Item -LiteralPath $Path -Force;try{$streams=@(Get-Item -LiteralPath $Path -Force -Stream * -ErrorAction Stop)}catch{if($item.PSIsContainer){return};Fail 'PATH'};if($streams.Count-gt32){Fail 'PATH'};foreach($stream in $streams){if([string]$stream.Stream -cne':$DATA'){Fail 'PATH'}} }
function Hash([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() }
function Read-ClosedJson([string]$Path) { try { $bytes=[IO.File]::ReadAllBytes($Path); if($bytes.Length -gt 4194304){Fail 'INPUT'}; $text=[Text.UTF8Encoding]::new($false,$true).GetString($bytes); if($text.Contains("`r") -or -not $text.EndsWith("`n")){Fail 'INPUT'};$doc=[Text.Json.JsonDocument]::Parse($text);try{Assert-M12JsonNoDuplicateProperties $doc.RootElement}finally{$doc.Dispose()}; return $text|ConvertFrom-Json -Depth 64 -ErrorAction Stop } catch { Fail 'INPUT' } }
function Assert-String([object]$Value,[string]$Code='INPUT') { if($null -eq $Value -or $Value -isnot [string] -or [string]::IsNullOrWhiteSpace($Value) -or $Value.Length -gt 512){Fail $Code} }
function Get-M12CanonicalPurl([string]$Type,[string]$Name,[string]$Version) { Assert-String $Type 'OUTPUT';Assert-String $Name 'OUTPUT';Assert-String $Version 'OUTPUT';if($Name.Contains('..')-or$Name.Contains('\')-or$Name.Contains(':')-or$Version.Contains('..')-or$Version.Contains('\')){Fail 'OUTPUT'};$kind=$Type.ToLowerInvariant();$canonicalName=if($kind-in @('nuget','npm','generic')){$Name.ToLowerInvariant()}else{$Name};$encode={param([string]$Part) [Uri]::EscapeDataString($Part).Replace('%21','!').Replace('%27',"'").Replace('%28','(').Replace('%29',')').Replace('%2A','*')};$encoded=(@($canonicalName.Split('/')|ForEach-Object{&$encode $_})-join'/');return "pkg:$kind/$encoded@$(&$encode $Version)" }
function Enter-M12CleanEnvironment([string]$Scratch) { $saved=@{};$names=@('GIT_SSH','GIT_ASKPASS','SSH_ASKPASS','GIT_GUI','GIT_CONFIG','GIT_CONFIG_GLOBAL','GIT_CONFIG_SYSTEM','GIT_CONFIG_NOSYSTEM','GIT_CONFIG_COUNT','GIT_PAGER','GIT_EDITOR','GCM_INTERACTIVE');foreach($entry in [Environment]::GetEnvironmentVariables().GetEnumerator()){if(([string]$entry.Key)-match'^(?i:DOTNET|MSBUILD|NUGET|NODE_OPTIONS$|NODE_PATH$|npm_config_|PNPM|COREPACK)' -or $names -contains [string]$entry.Key){$saved[[string]$entry.Key]=[string]$entry.Value;[Environment]::SetEnvironmentVariable([string]$entry.Key,$null)}};$controlled=@{DOTNET_CLI_HOME=(Join-Path $Scratch 'dotnet-home');NUGET_PACKAGES=(Join-Path $Scratch 'nuget-cache');COREPACK_HOME=(Join-Path $Scratch 'corepack-cache');npm_config_cache=(Join-Path $Scratch 'npm-cache');DOTNET_NOLOGO='1';DOTNET_SKIP_FIRST_TIME_EXPERIENCE='1'};foreach($name in $controlled.Keys){[Environment]::SetEnvironmentVariable($name,$controlled[$name])};return $saved }
function Assert-M12ToolEnvironmentClean { $gitNames=@('GIT_SSH','GIT_ASKPASS','SSH_ASKPASS','GIT_GUI','GIT_CONFIG','GIT_CONFIG_GLOBAL','GIT_CONFIG_SYSTEM','GIT_CONFIG_NOSYSTEM','GIT_CONFIG_COUNT','GIT_PAGER','GIT_EDITOR','GCM_INTERACTIVE');foreach($entry in [Environment]::GetEnvironmentVariables().GetEnumerator()){if((([string]$entry.Key)-match'^(?i:DOTNET|MSBUILD|NUGET|NODE_OPTIONS$|NODE_PATH$|npm_config_|PNPM|COREPACK)') -or $gitNames -contains [string]$entry.Key){if(-not[string]::IsNullOrWhiteSpace([string]$entry.Value)){Fail 'INPUT'}}} }
function Assert-M12PowerShellVersion([Version]$Version) { if($Version -lt [Version]'7.5'){Fail 'HOST'} }
function Exit-M12CleanEnvironment([hashtable]$Saved) { foreach($name in @('DOTNET_CLI_HOME','NUGET_PACKAGES','COREPACK_HOME','npm_config_cache','DOTNET_NOLOGO','DOTNET_SKIP_FIRST_TIME_EXPERIENCE')){[Environment]::SetEnvironmentVariable($name,$null)};foreach($name in $Saved.Keys){[Environment]::SetEnvironmentVariable($name,$Saved[$name])} }
function Assert-M12RelativePath([string]$Path) { if([string]::IsNullOrWhiteSpace($Path)-or$Path.Length-gt512-or$Path.StartsWith('/')-or$Path.StartsWith('\\')-or$Path.Contains('\')-or$Path.Contains(':')-or(@($Path.Split('/')|Where-Object{$_-in @('','.','..')}).Count-ne0)){Fail 'CONTRACT'} }
function Assert-M12TrustedTree([string]$Root) {
    $gitRoot=Join-Path $Root '.git';if(-not(Test-Path -LiteralPath $gitRoot -PathType Container)){Fail 'HOST'};Assert-M12NoReparse $gitRoot $Root
    $env:GIT_DIR=$null;$env:GIT_WORK_TREE=$null;$env:GIT_INDEX_FILE=$null;$env:GIT_OBJECT_DIRECTORY=$null;$env:GIT_ALTERNATE_OBJECT_DIRECTORIES=$null;$env:GIT_CEILING_DIRECTORIES=$null;$env:GIT_COMMON_DIR=$null;$env:GIT_NAMESPACE=$null;$env:GIT_PREFIX=$null;$env:GIT_EXEC_PATH=$null;$env:GIT_SSH_COMMAND=$null;$env:GIT_CONFIG_COUNT='0';$env:GIT_CONFIG_NOSYSTEM='1';$env:GIT_CONFIG_GLOBAL='NUL';$env:GIT_CONFIG_SYSTEM='NUL';$env:GIT_TERMINAL_PROMPT='0';$env:GIT_OPTIONAL_LOCKS='0'
    $headPath=Join-Path $gitRoot 'HEAD';$headLocked=Read-M12LockedBytes $headPath $Root 4096;$head=[Text.UTF8Encoding]::new($false,$true).GetString($headLocked.Bytes).Trim();if($head -match '^ref: (refs/.+)$'){$refName=$Matches[1];$parts=$refName.Split('/');if($parts.Count-lt2-or$parts[0]-cne'refs'-or(@($parts|Where-Object{[string]::IsNullOrEmpty($_)-or$_-in @('.','..')-or$_-notmatch'^[A-Za-z0-9._-]+$'}).Count-ne0)){Fail 'HOST'};$refPath=Join-Path $gitRoot ($refName.Replace('/','\'));$rootFull=[IO.Path]::GetFullPath($Root);$refFull=[IO.Path]::GetFullPath($refPath);if(-not$refFull.StartsWith($rootFull+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){Fail 'HOST'};if(-not(Test-Path -LiteralPath $refPath -PathType Leaf)){Fail 'HOST'};$head=[Text.UTF8Encoding]::new($false,$true).GetString((Read-M12LockedBytes $refPath $Root 4096).Bytes).Trim()};if($head -notmatch '^[0-9a-f]{40}$'){Fail 'HOST'}; return $head
}
function Get-M12ExpectedManifestPaths([string]$Root) {
    $expected=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);$queue=[Collections.Generic.Queue[string]]::new();foreach($item in @('src/SqlObserver.Server/SqlObserver.Server.csproj','src/SqlObserver.Collector/SqlObserver.Collector.csproj','src/SqlObserver.McpStdio/SqlObserver.McpStdio.csproj')){$queue.Enqueue($item)};foreach($item in @('Directory.Packages.props','Directory.Build.props','global.json','web/package.json','web/pnpm-lock.yaml','web/tools/web-asset-manifest.mjs','web/contracts/web-asset-manifest.v1.schema.json')){[void]$expected.Add($item)}
    # Validate the project-reference graph with a case-insensitive active stack. The
    # expected-set traversal below remains responsible for the manifest closure, but
    # this DFS ensures self-cycles and A -> B -> A cannot be hidden by de-duplication.
    $active=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);$completed=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);$visit=$null;$visit={param([string]$Current);if($active.Contains($Current)){Fail 'CONTRACT'};if($completed.Contains($Current)){return};Assert-M12RelativePath $Current;$path=Join-Path $Root $Current;$locked=Read-M12LockedBytes $path $Root 1048576;$memory=[IO.MemoryStream]::new($locked.Bytes,$false);$xml=[Xml.XmlDocument]::new();$xml.XmlResolver=$null;$settings=[Xml.XmlReaderSettings]::new();$settings.DtdProcessing=[Xml.DtdProcessing]::Prohibit;$settings.XmlResolver=$null;try{$reader=[Xml.XmlReader]::Create($memory,$settings);try{$xml.Load($reader)}finally{$reader.Dispose()}}finally{$memory.Dispose()};[void]$active.Add($Current);foreach($reference in @($xml.SelectNodes('//*[local-name()="ProjectReference"]'))){$include=[string]$reference.GetAttribute('Include');if([string]::IsNullOrWhiteSpace($include)){Fail 'CONTRACT'};$next=[IO.Path]::GetFullPath((Join-Path (Split-Path $path -Parent) $include));$rootFull=[IO.Path]::GetFullPath($Root);if(-not$next.StartsWith($rootFull+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){Fail 'CONTRACT'};$relative=$next.Substring(($rootFull+[IO.Path]::DirectorySeparatorChar).Length).Replace('\','/');Assert-M12RelativePath $relative;&$visit $relative};[void]$active.Remove($Current);[void]$completed.Add($Current)};foreach($item in @('src/SqlObserver.Server/SqlObserver.Server.csproj','src/SqlObserver.Collector/SqlObserver.Collector.csproj','src/SqlObserver.McpStdio/SqlObserver.McpStdio.csproj')){&$visit $item}
    while($queue.Count-gt0){$current=$queue.Dequeue();if(-not$expected.Add($current)){continue};Assert-M12RelativePath $current;$path=Join-Path $Root $current;$locked=Read-M12LockedBytes $path $Root 1048576;$memory=[IO.MemoryStream]::new($locked.Bytes,$false);$xml=[Xml.XmlDocument]::new();$xml.XmlResolver=$null;$settings=[Xml.XmlReaderSettings]::new();$settings.DtdProcessing=[Xml.DtdProcessing]::Prohibit;$settings.XmlResolver=$null;try{$reader=[Xml.XmlReader]::Create($memory,$settings);try{$xml.Load($reader)}finally{$reader.Dispose()}}finally{$memory.Dispose()};foreach($reference in @($xml.SelectNodes('//*[local-name()="ProjectReference"]'))){$include=[string]$reference.GetAttribute('Include');if([string]::IsNullOrWhiteSpace($include)){Fail 'CONTRACT'};$next=[IO.Path]::GetFullPath((Join-Path (Split-Path $path -Parent) $include));$rootFull=[IO.Path]::GetFullPath($Root);if(-not$next.StartsWith($rootFull+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){Fail 'CONTRACT'};$relative=$next.Substring(($rootFull+[IO.Path]::DirectorySeparatorChar).Length).Replace('\','/');Assert-M12RelativePath $relative;$queue.Enqueue($relative)}};foreach($project in @($expected|Where-Object{$_-match '[.]csproj$'})){$projectDir=Split-Path $project -Parent;$lock=Join-Path $Root (Join-Path $projectDir 'packages.lock.json');if(Test-Path -LiteralPath $lock -PathType Leaf){[void]$expected.Add((Join-Path $projectDir 'packages.lock.json').Replace('\','/'))}elseif($projectDir-notmatch 'SqlObserver[.]Reporting$'){Fail 'CONTRACT'}};return $expected
}
function Assert-Manifest([string]$Root,[object]$Manifest) {
    if((@($Manifest.PSObject.Properties.Name)-join'|')-cne'$schema|schemaVersion|manifestId|roots|files'-or$Manifest.'$schema' -cne $InputsSchemaName -or $Manifest.schemaVersion -ne 1 -or $Manifest.manifestId -cne 'm12-sbom-inputs' -or @($Manifest.files).Count -ne 40){Fail 'CONTRACT'}
    $expectedRoots=@('src/SqlObserver.Server/SqlObserver.Server.csproj','src/SqlObserver.Collector/SqlObserver.Collector.csproj','src/SqlObserver.McpStdio/SqlObserver.McpStdio.csproj');if((@($Manifest.roots)-join '|')-cne($expectedRoots-join '|')){Fail 'CONTRACT'};$expected=Get-M12ExpectedManifestPaths $Root;$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);foreach($pin in @($Manifest.files)){if($null-eq$pin-or$pin.PSObject.Properties.Name.Count-ne2-or$pin.sha256-notmatch'^[0-9a-f]{64}$'){Fail 'CONTRACT'};Assert-M12RelativePath ([string]$pin.path);$relative=[string]$pin.path;if(-not$seen.Add($relative)-or-not$expected.Contains($relative)){Fail 'CONTRACT'};$path=Join-Path $Root $relative;if(-not(Test-Path -LiteralPath $path -PathType Leaf)){Fail 'CONTRACT'};$locked=Read-M12LockedBytes $path $Root 16777216;if($locked.Hash-cne$pin.sha256){Fail 'CONTRACT'}};if($seen.Count-ne$expected.Count){Fail 'CONTRACT'}
}
function Assert-Contract([string]$Root) {
    $dir=Join-Path $Root 'release/certification';Assert-M12NoAlternateDataStreams $dir $Root;$cp=Join-Path $dir $ContractName;$sp=Join-Path $dir $SchemaName;$ip=Join-Path $dir $InputsName;$is=Join-Path $dir $InputsSchemaName;$bp=Join-Path $dir $SbomSchemaName;$pp=Join-Path $dir 'm12-supply-chain-contract.v1.assets.sha256'
    foreach($p in @($cp,$sp,$ip,$is,$bp,$pp)){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){Fail 'CONTRACT'}}
    $assetPin=Read-M12LockedBytes $pp $Root 1048576;if($assetPin.Hash-cne$ApprovedAssetManifestSha256){Fail 'CONTRACT'};Assert-M12AssetPins $Root $pp;[void](Read-M12ClosedJsonPath $bp $Root 16777216)
    $c=Read-M12ClosedJsonPath $cp $Root;$s=Read-M12ClosedJsonPath $sp $Root;$m=Read-M12ClosedJsonPath $ip $Root;if((@($c.PSObject.Properties.Name)-join'|')-cne'$schema|schemaVersion|contractId|producerId|artifactKind|caseId|environments|requiredFacts|factPredicates|inputManifest|sbomSchema|outputFiles|generation|bounds'-or(@($s.PSObject.Properties.Name)-join'|')-cne'$schema|$id|title|type|additionalProperties|required|properties'-or$s.additionalProperties-ne$false-or$c.'$schema'-cne$SchemaName-or$c.schemaVersion-ne1-or$c.contractId-cne'sqlobserver-m12-supply-chain'-or$c.producerId-cne$ProducerId-or$c.artifactKind-cne$ArtifactKind-or$c.caseId-cne'm12-sbom'-or$c.inputManifest-cne$InputsName-or$c.sbomSchema-cne$SbomSchemaName){Fail 'CONTRACT'}
    if((@($c.environments)-join '|') -cne 'release-windows-server-2022|release-windows-server-2025' -or (@($c.requiredFacts)-join '|') -cne 'os|architecture|sbom' -or $c.factPredicates.os -cne 'windows' -or $c.factPredicates.architecture -cne 'x64' -or $c.factPredicates.sbom -ne $true){Fail 'CONTRACT'}
