function Assert-M12NoDescendants([Collections.Generic.HashSet[int]]$ProcessIds) { if(-not$IsWindows){return};$roots=[Collections.Generic.HashSet[int]]::new();foreach($id in $ProcessIds){[void]$roots.Add([int]$id)};for($sweep=0;$sweep-lt 3;$sweep++){$snapshot=@(Get-CimInstance Win32_Process -ErrorAction Stop);$children=@{};foreach($proc in $snapshot){$parent=[int]$proc.ParentProcessId;if(-not$children.ContainsKey($parent)){$children[$parent]=[Collections.Generic.List[int]]::new()};$children[$parent].Add([int]$proc.ProcessId)};$queue=[Collections.Generic.Queue[int]]::new();foreach($root in $roots){$queue.Enqueue($root)};$seen=[Collections.Generic.HashSet[int]]::new();while($queue.Count-gt 0){$current=$queue.Dequeue();if(-not$seen.Add($current)){continue};if($children.ContainsKey($current)){foreach($child in $children[$current]){if(-not$roots.Contains($child)){Fail 'PROCESS'};$queue.Enqueue($child)}}};[Threading.Thread]::Sleep(50)}}
