function Assert-M12NoReparse([string]$Path,[string]$Root) { $full=[IO.Path]::GetFullPath($Path);$base=[IO.Path]::GetFullPath($Root).TrimEnd('\','/');if(-not($full-eq$base-or$full.StartsWith($base+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase))){Fail 'PATH'};$cursor=$full;while($null-ne$cursor){if(Test-Path -LiteralPath $cursor){$info=Get-Item -LiteralPath $cursor -Force;if($info.Attributes-band[IO.FileAttributes]::ReparsePoint){Fail 'PATH'}};$parent=[IO.Directory]::GetParent($cursor);$parentFull=if($null-ne$parent){$parent.FullName.TrimEnd('\','/')}else{$null};if($null-eq$parent-or$parentFull-eq$cursor){break};$cursor=$parentFull};if($IsWindows-and(Test-Path -LiteralPath $full)){ $item=Get-Item -LiteralPath $full -Force;if(-not$item.PSIsContainer){$streams=@(Get-Item -LiteralPath $full -Force -Stream * -ErrorAction Stop);if($streams.Count-gt32){Fail 'PATH'};foreach($stream in $streams){if([string]$stream.Stream -cne':$DATA'){Fail 'PATH'}}}} }
