        while(-not($od-and$ed-and$process.HasExited)){foreach($id in @($native.ProcessIds)){[void]$observed.Add($id)};[Threading.Thread]::Sleep(25);if(-not$od-and$ot.IsCompleted){$n=$ot.GetAwaiter().GetResult();if($n-eq 0){$od=$true}elseif($output.Length+$n-gt$MaximumOutput){$tooLarge=$true}else{$output.Write($ob,0,$n);$ot=$native.StandardOutput.ReadAsync($ob,0,$ob.Length)}};if(-not$ed-and$et.IsCompleted){$n=$et.GetAwaiter().GetResult();if($n-eq 0){$ed=$true}elseif($error.Length+$n-gt$MaximumError){$tooLarge=$true}else{$error.Write($eb,0,$n);$et=$native.StandardError.ReadAsync($eb,0,$eb.Length)}};if($tooLarge-or[Environment]::TickCount64-ge$deadline){$timedOut=-not$tooLarge;$native.Terminate();break}}
        foreach($id in @($native.ProcessIds)){[void]$observed.Add($id)};if(-not$native.WaitForZero(2000)-or$native.ActiveProcesses-ne 0){Fail 'PROCESS'};Assert-M12ObservedPidsExited $observed;Assert-M12NoDescendants $observed;return [pscustomobject]@{ExitCode=$process.ExitCode;Output=[Text.Encoding]::UTF8.GetString($output.ToArray());Error=[Text.Encoding]::UTF8.GetString($error.ToArray());TooLarge=$tooLarge;TimedOut=$timedOut}
    } finally { try { if($null-ne$native){if($native.ActiveProcesses-gt 0){$native.Terminate()};if(-not$native.WaitForZero(2000)-or$native.ActiveProcesses-ne 0){$cleanupFailure=$true};$native.Dispose()} } catch {$cleanupFailure=$true};$output.Dispose();$error.Dispose();if($cleanupFailure){Fail 'PROCESS'} }
